// Normaliza o payload da Evolution e decide se vale processar.
//
// A Evolution manda TODO evento para o webhook, inclusive as mensagens que o
// proprio numero envia (`fromMe: true`). Sem este corte, o agente responderia
// a si mesmo — laco infinito que so para quando o numero e banido.
//
// Grupo tambem fica de fora: `@g.us` no remoteJid. Responder em grupo expoe a
// conversa comercial para gente que nunca pediu nada.
const e = $input.first().json;
const d = e.data || {};
const k = d.key || {};

const texto =
  d.message?.conversation ??
  d.message?.extendedTextMessage?.text ??
  '';

const jid = k.remoteJid || '';
const numero = jid.split('@')[0];

const processar =
  e.event === 'messages.upsert' &&
  k.fromMe !== true &&
  !jid.endsWith('@g.us') &&
  texto.trim().length > 0;

return [{ json: {
  processar,
  numero,
  nome: d.pushName || null,
  texto: texto.trim(),
  instancia: e.instance || null,
} }];
